--
-- Name: createsetmaterializedview(character varying, character varying); Type: FUNCTION; Schema: public; Owner: managuide
--

CREATE FUNCTION public.createsetmaterializedview(character varying, character varying) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
    _code ALIAS FOR $1;
    _language ALIAS FOR $2;
    command character varying;
BEGIN

    command := 'CREATE MATERIALIZED VIEW IF NOT EXISTS matv_cmset_' || _code || '_' || _language || ' AS ';
    command := command || 'SELECT card_count,
        code,
        is_foil_only,
        is_online_only,
        logo_code,
        mtgo_code,
        keyrune_unicode,
        keyrune_class,
        year_section,
        name,
        release_date,
        tcgplayer_id,
        (
            SELECT row_to_json(x) FROM (
                SELECT sb.code, sb.name
                FROM cmsetblock sb WHERE sb.code = s.cmsetblock
                LIMIT 1
            ) x
        ) AS set_block,
        (
            SELECT row_to_json(x) FROM (
                SELECT st.name
                FROM cmsettype st WHERE st.name = s.cmsettype
                LIMIT 1
            ) x
        ) AS set_type,
        array(
            SELECT row_to_json(x) FROM (
                SELECT l.code, l.display_code, l.name
                FROM cmset_language sl left join cmlanguage l on sl.cmlanguage = l.code
                WHERE sl.cmset = s.code
                LIMIT 100
            ) x
        ) AS languages,
        array_to_json(
            array(SELECT selectCards(''' || _code || ''', ''' || _language || ''', ''name'', ''ASC''))
        ) AS cards
        FROM cmset s WHERE s.code = ''' || _code || '''';

    EXECUTE command;

    RETURN;
END;
$_$;


ALTER FUNCTION public.createsetmaterializedview(character varying, character varying) OWNER TO managuide;

--
-- Name: createsetsmaterializedview(); Type: FUNCTION; Schema: public; Owner: managuide
--

CREATE FUNCTION public.createsetsmaterializedview() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    
BEGIN
    CREATE MATERIALIZED VIEW IF NOT EXISTS matv_cmsets AS 
        SELECT card_count,
                code,
                is_foil_only,
                is_online_only,
                logo_code,
                mtgo_code,
                keyrune_unicode,
                keyrune_class,
                year_section,
                name,
                release_date,
                tcgplayer_id,
                cmset_parent,
                (
                    SELECT row_to_json(x) FROM (
                        SELECT sb.code, sb.name
                        FROM cmsetblock sb WHERE sb.code = s.cmsetblock
                        LIMIT 1
                    ) x
                ) AS set_block,
                (
                    SELECT row_to_json(x) FROM (
                        SELECT st.name
                        FROM cmsettype st WHERE st.name = s.cmsettype
                        LIMIT 1
                    ) x
                ) AS set_type,
                (
                    SELECT row_to_json(x) FROM (
                        SELECT sp.code
                        FROM cmset sp WHERE sp.code = s.cmset_parent
                        LIMIT 1
                    ) x
                ) AS set_parent,
                array(
                    SELECT row_to_json(x) FROM (
                        SELECT l.code, l.display_code, l.name
                        FROM cmset_language sl left join cmlanguage l on sl.cmlanguage = l.code
                        WHERE sl.cmset = s.code
                        LIMIT 100
                    ) x
                ) AS languages
        FROM cmset s WHERE s.card_count > 0
        GROUP BY cmset_parent, card_count, code
        ORDER BY release_date DESC, cmset_parent DESC, name ASC;

    RETURN;
END;
$$;


ALTER FUNCTION public.createsetsmaterializedview() OWNER TO managuide;

--
-- Name: deletecard(character varying); Type: FUNCTION; Schema: public; Owner: managuide
--

CREATE FUNCTION public.deletecard(character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$
DECLARE
    _new_id_or_id ALIAS FOR $1;

    pkey character varying;
    _new_id character varying;
BEGIN
    SELECT new_id INTO _new_id FROM cmcard c where c.new_id = _new_id_or_id;

    IF NOT FOUND THEN
        SELECT new_id INTO _new_id FROM cmcard c where c.id = _new_id_or_id;
    END IF;

    DELETE from cmcard_color WHERE cmcard = _new_id;
    DELETE from cmcard_coloridentity WHERE cmcard = _new_id;
	DELETE from cmcard_colorindicator WHERE cmcard = _new_id;
	DELETE from cmcard_component_part WHERE cmcard = _new_id;
    DELETE from cmcard_component_part WHERE cmcard_part = _new_id;
	DELETE from cmcard_face WHERE cmcard_face = _new_id;
	DELETE from cmcard_face WHERE cmcard = _new_id;
    DELETE from cmcard_format_legality WHERE cmcard = _new_id;
    DELETE from cmcard_frameeffect WHERE cmcard = _new_id;
	DELETE from cmcard_otherlanguage WHERE cmcard = _new_id;
    DELETE from cmcard_otherprinting WHERE cmcard = _new_id;
    DELETE from cmcard_subtype WHERE cmcard = _new_id;
    DELETE from cmcard_supertype WHERE cmcard = _new_id;
    DELETE from cmcardprice WHERE cmcard = _new_id;
	DELETE from cmcard_variation WHERE cmcard = _new_id;
    DELETE from cmcard_game WHERE cmcard = _new_id;
    DELETE from cmcard_artist WHERE cmcard = _new_id;
    DELETE from cmcard_keyword WHERE cmcard = _new_id;
    DELETE from cmcard WHERE new_id = _new_id;

    RETURN true;
END;
$_$;


ALTER FUNCTION public.deletecard(character varying) OWNER TO managuide;

--
-- Name: deleteset(character varying); Type: FUNCTION; Schema: public; Owner: managuide
--

CREATE FUNCTION public.deleteset(character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
    _code ALIAS FOR $1;

    _new_id character varying;
    _card_count integer := 0;
BEGIN

    FOR _new_id IN SELECT new_id FROM cmcard where cmset = _code LOOP
        PERFORM deleteCard(_new_id);
        _card_count := _card_count + 1;
    END LOOP;

    DELETE FROM cmset_language WHERE cmset = _code;
    DELETE FROM cmset WHERE code = _code;

    RETURN _card_count;
END;
$_$;


ALTER FUNCTION public.deleteset(character varying) OWNER TO managuide;

--
-- Name: searchcards(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: managuide
--

CREATE FUNCTION public.searchcards(character varying, character varying, character varying) RETURNS TABLE(new_id character varying, collector_number character varying, face_order integer, loyalty character varying, mana_cost character varying, number_order double precision, name character varying, name_section character varying, printed_name character varying, printed_type_line character varying, type_line character varying, power character varying, toughness character varying, tcgplayer_id integer, released_at date, art_crop_url character varying, normal_url character varying, png_url character varying, set json, rarity json, language json, layout json, prices json[], faces json[], supertypes json[])
    LANGUAGE plpgsql
    AS $_$
DECLARE
    _query ALIAS FOR $1;
    _sortedBy ALIAS FOR $2;
    _orderBy ALIAS FOR $3;
    command character varying;
BEGIN
    _query := lower(_query);
    IF lower(_sortedBy) = 'set_name' THEN
        _sortedBy = 's.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
	IF lower(_sortedBy) = 'set_release' THEN
        _sortedBy = 's.release_date ' || _orderBy || ', s.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'collector_number' THEN
        _sortedBy = 'c.number_order ' || _orderBy || ', c.released_at DESC';
    END IF;
    IF lower(_sortedBy) = 'name' THEN
        _sortedBy = 'regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy || ', c.released_at DESC';
    END IF;
    IF lower(_sortedBy) = 'cmc' THEN
        _sortedBy = 'c.cmc ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy || ', c.released_at DESC';
    END IF;
    IF lower(_sortedBy) = 'type' THEN
        _sortedBy = 'c.type_line ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy || ', c.released_at DESC';
    END IF;
    IF lower(_sortedBy) = 'rarity' THEN
        _sortedBy = 'r.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy || ', c.released_at DESC';
    END IF;

    command := 'SELECT DISTINCT ON (regexp_replace(c.name, ''"'', '''', ''g''))
                    c.new_id,
                    c.collector_number,
                    c.face_order,
                    c.loyalty,
                    c.mana_cost,
                    c.number_order,
                    c.name,
                    c.name_section,
                    c.printed_name,
                    c.printed_type_line,
                    c.type_line,
	                c.power,
                    c.toughness,
                    c.tcgplayer_id,
                    c.released_at,
                    c.art_crop_url,
                    c.normal_url,
                    c.png_url,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT s.code, s.name, s.keyrune_class, s.keyrune_unicode
                            FROM cmset s WHERE s.code = c.cmset
                            LIMIT 1
                        ) x
                    ) AS set,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT r.name
                            FROM cmrarity r WHERE r.name = c.cmrarity
                            LIMIT 1
                        ) x
                    ) AS rarity,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT l.code, l.name
                            FROM cmlanguage l WHERE l.code = c.cmlanguage
                            LIMIT 1
                        ) x
                    ) AS language,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.code, v.name, v.description
                            FROM cmlayout v
                            WHERE v.code = c.cmlayout
                            LIMIT 1
                        ) x
                    ) AS layout,
                    array(
                        SELECT row_to_json(x) FROM (
                            SELECT v.id, v.low, v.median, v.high, v.market, v.direct_low, v.is_foil, v.date_updated
                            FROM cmcardprice v
                            WHERE v.cmcard = c.new_id
                            LIMIT 1
                        ) x
                    ) AS prices ';

    -- Faces
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (
                            SELECT
                                new_id,
                                collector_number,
                                face_order,
                                loyalty,
                                mana_cost,
                                number_order,
                                name,
                                name_section,
                                printed_name,
                                printed_type_line,
                                type_line,
	                            power,
                                toughness,
                                art_crop_url,
                                normal_url,
                                png_url
                            FROM cmcard d left join cmcard_face w on w.cmcard_face = d.new_id
                            WHERE w.cmcard = c.new_id
                            ORDER BY face_order
                            LIMIT 10
                        ) x
                    ) AS faces ';

    -- Supertypes
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (
                            SELECT w.name
                            FROM cmcard_supertype v left join cmcardtype w on v.cmcardtype = w.name
                            WHERE v.cmcard = c.new_id
                            LIMIT 50
                        ) x
                    ) AS supertypes ';               

    command := command || 'FROM cmcard c ';
    command := command || 'WHERE c.cmlanguage = ''en'' ';
    command := command || 'AND c.new_id NOT IN(select cmcard_face from cmcard_face) ';
    command := command || 'AND lower(c.name) LIKE ''%' || _query || '%'' ';
    command := command || 'ORDER BY ' || _sortedBy || '';

    RETURN QUERY EXECUTE command;
END;
$_$;


ALTER FUNCTION public.searchcards(character varying, character varying, character varying) OWNER TO managuide;

--
-- Name: searchrules(character varying); Type: FUNCTION; Schema: public; Owner: managuide
--

CREATE FUNCTION public.searchrules(character varying) RETURNS TABLE(id integer, term character varying, term_section character varying, definition character varying, "order" double precision, parent json, children json[])
    LANGUAGE plpgsql
    AS $_$
DECLARE
    _query ALIAS FOR $1;
    command character varying;
BEGIN
    _query := lower(_query);

    command := 'SELECT id,
                    term,
                    term_section,
                    definition,
                    "order",
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT p.id, p.term, p.definition
                            FROM cmrule p WHERE p.id = s.cmrule_parent
                        ) x
                    ) AS parent';

    -- Children
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (' ||
                            command || ', (SELECT children from selectRules(c.id))'
                            ' FROM cmrule c
                            WHERE c.cmrule_parent = s.id ORDER BY c.term'
                        ') x
                    ) AS children FROM cmrule s';

    command := command || ' WHERE lower(s.term) LIKE ''%' || _query || '%'' ';
    command := command || ' OR lower(s.definition) LIKE ''%' || _query || '%'' ';

    command := command || ' ORDER BY s.order ASC';

    RETURN QUERY EXECUTE command;
END;
$_$;


ALTER FUNCTION public.searchrules(character varying) OWNER TO managuide;

--
-- Name: selectcard(character varying); Type: FUNCTION; Schema: public; Owner: managuide
--

CREATE FUNCTION public.selectcard(character varying) RETURNS TABLE(collector_number character varying, cmc double precision, face_order integer, flavor_text character varying, is_foil boolean, is_full_art boolean, is_highres_image boolean, is_nonfoil boolean, is_oversized boolean, is_reserved boolean, is_story_spotlight boolean, loyalty character varying, mana_cost character varying, number_order double precision, name character varying, name_section character varying, oracle_text character varying, power character varying, printed_name character varying, printed_text character varying, toughness character varying, arena_id integer, mtgo_id integer, tcgplayer_id integer, hand_modifier character varying, life_modifier character varying, is_booster boolean, is_digital boolean, is_promo boolean, released_at date, is_textless boolean, mtgo_foil_id integer, is_reprint boolean, new_id character varying, printed_type_line character varying, type_line character varying, multiverse_ids integer[], art_crop_url character varying, normal_url character varying, png_url character varying, set json, rarity json, language json, layout json, watermark json, frame json, artists json[], colors json[], color_identities json[], color_indicators json[], component_parts json[], faces json[], other_languages json[], other_printings json[], variations json[], format_legalities json[], frame_effects json[], subtypes json[], supertypes json[], prices json[], rulings json[])
    LANGUAGE plpgsql
    AS $_$
DECLARE
    _new_id ALIAS FOR $1;
	_collector_number character varying;
    command character varying;	
BEGIN
	SELECT c.collector_number INTO _collector_number FROM cmcard c where c.new_id = _new_id;
	
    command := 'SELECT
                    c.collector_number,
                    c.cmc,
                    c.face_order,
                    c.flavor_text,
                    c.is_foil,
                    c.is_full_art,
                    c.is_highres_image,
                    c.is_nonfoil,
                    c.is_oversized,
                    c.is_reserved,
                    c.is_story_spotlight,
                    c.loyalty,
                    c.mana_cost,
                    c.number_order,
                    c.name,
                    c.name_section,
                    c.oracle_text,
                    c.power,
                    c.printed_name,
                    c.printed_text,
                    c.toughness,
                    c.arena_id,
                    c.mtgo_id,
                    c.tcgplayer_id,
                    c.hand_modifier,
                    c.life_modifier,
                    c.is_booster,
                    c.is_digital,
                    c.is_promo,
                    c.released_at,
                    c.is_textless,
                    c.mtgo_foil_id,
                    c.is_reprint,
                    c.new_id,
                    c.printed_type_line,
                    c.type_line,
                    c.multiverse_ids,
                    c.art_crop_url,
                    c.normal_url,
                    c.png_url,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.code, v.name, v.keyrune_class, v.keyrune_unicode
                            FROM cmset v WHERE v.code = c.cmset
                            LIMIT 1
                        ) x
                    ) AS set,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.name
                            FROM cmrarity v
                            WHERE v.name = c.cmrarity
                            LIMIT 1
                        ) x
                    ) AS rarity,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.code, v.display_code, v.name
                            FROM cmlanguage v
                            WHERE v.code = c.cmlanguage
                            LIMIT 1
                        ) x
                    ) AS language,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.code, v.name, v.description
                            FROM cmlayout v
                            WHERE v.code = c.cmlayout
                            LIMIT 1
                        ) x
                    ) AS layout,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.name
                            FROM cmwatermark v
                            WHERE v.name = c.cmwatermark
                            LIMIT 1
                        ) x
                    ) AS watermark,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.name
                            FROM cmframe v
                            WHERE v.name = c.cmframe
                            LIMIT 1
                        ) x
                    ) AS frame,
                    array(
                        SELECT row_to_json(x) FROM (
                            SELECT w.first_name, w.last_name, w.name, w.name_section, w.info
                            FROM cmcard_artist v left join cmartist w on v.cmartist = w.name
                            WHERE v.cmcard = c.new_id
                            LIMIT 10
                        ) x
                    ) AS artists,
                    array(
                        SELECT row_to_json(x) FROM (
                            SELECT w.name, w.symbol
                            FROM cmcard_color v left join cmcolor w on v.cmcolor = w.symbol
                            WHERE v.cmcard = c.new_id
                            LIMIT 10
                        ) x
                    ) AS colors,
                    array(
                        SELECT row_to_json(x) FROM (
                            SELECT w.name, w.symbol
                            FROM cmcard_coloridentity v left join cmcolor w on v.cmcolor = w.symbol
                            WHERE v.cmcard = c.new_id
                            LIMIT 10
                        ) x
                    ) AS color_identities,
                    array(
                        SELECT row_to_json(x) FROM (
                            SELECT w.name, w.symbol
                            FROM cmcard_colorindicator v left join cmcolor w on v.cmcolor = w.symbol
                            WHERE v.cmcard = c.new_id
                            LIMIT 10
                        ) x
                    ) AS color_indicators ';

    -- Component Parts
	command := command ||
					', array(
                        SELECT row_to_json(x) FROM (
							SELECT
							(
								SELECT row_to_json(a) FROM (select w.name)
							a) AS component,
                            (
								SELECT row_to_json(b) FROM (
                                	select x.new_id,
                                    x.collector_number,
                                	x.name,
                                    x.name_section,
                                	x.printed_name,
                                    x.art_crop_url,
                                    x.normal_url,
                                    x.png_url,
                                    (
                                        SELECT row_to_json(x) FROM (
                                            SELECT v.code, v.name, v.keyrune_class, v.keyrune_unicode
                                            FROM cmset v WHERE v.code = x.cmset
                                            LIMIT 1
                                        ) x
                                    ) AS set,
                                    (
                                        SELECT row_to_json(x) FROM (
                                            SELECT v.code, v.name
                                            FROM cmlanguage v
                                            WHERE v.code = x.cmlanguage
                                            LIMIT 1
                                        ) x
                                    ) AS language,
                                    array(
                                        SELECT row_to_json(x) FROM (
                                            SELECT
                                                new_id,
                                                name,
                                                name_section,
                                                printed_name,
                                                art_crop_url,
                                                normal_url,
                                                png_url
                                            FROM cmcard c left join cmcard_face w on w.cmcard_face = c.new_id
                                            WHERE w.cmcard = x.new_id
                                            LIMIT 10
                                        ) x
                                    ) AS faces
								)
							b) AS card
                            FROM cmcard_component_part v left join cmcomponent w on v.cmcomponent = w.name
							left join cmcard x on v.cmcard_part = x.new_id
                            WHERE v.cmcard = c.new_id AND v.cmcard_part != c.new_id
                            LIMIT 100
                        ) x
                    ) AS component_parts ';
    -- Faces
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (' || command ||
                            'FROM cmcard c left join cmcard_face w on w.cmcard_face = c.new_id
                            WHERE w.cmcard = ''' || _new_id || '''' ||
                        ' LIMIT 10) x
                    ) AS faces ';

    -- Other Languages
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (
                            SELECT
                                x.cmcard_otherlanguage as new_id,
                                c.name,
                                c.name_section,
                                c.printed_name,
                                c.collector_number,
                                c.art_crop_url,
                                c.normal_url,
                                c.png_url,
                                (
                                    SELECT row_to_json(x) FROM (
                                        SELECT v.name
                                        FROM cmrarity v
                                        WHERE v.name = c.cmrarity
                                        LIMIT 1
                                    ) x
                                ) AS rarity,
                                (
                                    SELECT row_to_json(x) FROM (
                                        SELECT v.code, v.display_code, v.name
                                        FROM cmlanguage v
                                        WHERE v.code = w.code
                                        LIMIT 1
                                    ) x
                                ) AS language,
                                (
                                    SELECT row_to_json(x) FROM (
                                        SELECT y.code, y.name, y.keyrune_class, y.keyrune_unicode
                                        FROM cmset y
                                        WHERE y.code = c.cmset
                                        LIMIT 1
                                    ) x
                                ) AS set,
                                array(
                                    SELECT row_to_json(x) FROM (
                                        SELECT
                                            new_id,
                                            name,
                                            name_section,
                                            printed_name,
                                            art_crop_url,
                                            normal_url,
                                            png_url
                                        FROM cmcard c left join cmcard_face w on w.cmcard_face = c.new_id
                                        WHERE w.cmcard = x.cmcard_otherlanguage
                                        LIMIT 10
                                    ) x
                                ) AS faces
                            FROM cmcard c left join cmlanguage w on w.code = cmlanguage
                            left join cmcard_otherlanguage x on x.cmcard_otherlanguage = c.new_id
                            WHERE x.cmcard = ''' || _new_id || '''' || ' and x.cmcard_otherlanguage LIKE ''%' || _collector_number || '''' ||
                            ' group by w.code, x.cmcard_otherlanguage, c.cmset, c.name, c.name_section, c.printed_name, c.cmrarity, c.collector_number,
                              c.art_crop_url, c.normal_url, c.png_url 
							 order by w.code
                             LIMIT 50
                        ) x
                    ) AS other_languages ';

    -- Other Printings
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (
						    SELECT
                                c.new_id,
                                c.name,
                                c.name_section,
                                c.printed_name,
                                c.collector_number,
                                c.art_crop_url,
                                c.normal_url,
                                c.png_url,
								(
                                    SELECT row_to_json(x) FROM (
                                        SELECT v.name
                                        FROM cmrarity v
                                        WHERE v.name = c.cmrarity
                                        LIMIT 1
                                    ) x
                                ) AS rarity,
								(
                                    SELECT row_to_json(x) FROM (
                                        SELECT y.code, y.name, y.keyrune_class, y.keyrune_unicode
                                        FROM cmset y
                                        WHERE y.code = c.cmset
                                        LIMIT 1
                                    ) x
                                ) AS set,
								array(
                                    SELECT row_to_json(x) FROM (
                                        SELECT 
                                            new_id,
                                            name,
                                            name_section,
                                            printed_name,
                                            art_crop_url,
                                            normal_url,
                                            png_url
                                        FROM cmcard c left join cmcard_face w on w.cmcard_face = c.new_id
                                        WHERE w.cmcard = x.cmcard_otherprinting
                                        LIMIT 10
                                    ) x
                                ) AS faces,
                                array(
                                    SELECT row_to_json(x) FROM (
                                        SELECT id, v.market, v.is_foil
                                        FROM cmcardprice v
                                        WHERE v.cmcard = c.new_id
                                        LIMIT 1
                                    ) x
                                ) AS prices,
                                (
                                    SELECT row_to_json(x) FROM (
                                        SELECT v.code, v.name
                                        FROM cmlanguage v
                                        WHERE v.code = c.cmlanguage
                                    ) x
                                ) AS language
                            FROM cmcard c
                            left join cmcard_otherprinting x on x.cmcard_otherprinting = c.new_id
                            left join cmset y on y.code = c.cmset
                            WHERE x.cmcard = ''' || _new_id || '''' ||
                            ' order by y.release_date desc, c.collector_number
                            LIMIT 10
                        ) x
                    ) AS other_printings ';

    -- Variations
    command := command ||
                ', array(
                    SELECT row_to_json(x) FROM (
						SELECT c.new_id,
                            c.collector_number,
                            c.name,
                            c.name_section,
                            c.printed_name,
                            c.collector_number,
                            c.art_crop_url,
                            c.normal_url,
                            c.png_url,
                            (
                                SELECT row_to_json(x) FROM (
                                    SELECT v.name
                                    FROM cmrarity v
                                    WHERE v.name = c.cmrarity
                                    LIMIT 1
                                ) x
                            ) AS rarity,
                            (
                                SELECT row_to_json(x) FROM (
                                    SELECT y.code, y.name, y.keyrune_class, y.keyrune_unicode
                                    FROM cmset y
                                    WHERE y.code = c.cmset
                                    LIMIT 1
                                ) x
                            ) AS set,
                            array(
                                SELECT row_to_json(x) FROM (
                                    SELECT
                                        new_id,
                                        name,
                                        name_section,
                                        printed_name,
                                        art_crop_url,
                                        normal_url,
                                        png_url
                                    FROM cmcard c left join cmcard_face w on w.cmcard_face = c.new_id
                                    WHERE w.cmcard = x.cmcard_variation
                                    LIMIT 10
                                ) x
                            ) AS faces,
                            (
                                SELECT row_to_json(x) FROM (
                                    SELECT v.code, v.name
                                    FROM cmlanguage v
                                    WHERE v.code = c.cmlanguage
                                    LIMIT 1
                                ) x
                            ) AS language
                        FROM cmcard c
                        left join cmcard_variation x on x.cmcard_variation = c.new_id
                        WHERE x.cmcard = ''' || _new_id || '''' ||
                        ' order by c.collector_number
                        LIMIT 50
                    ) x
                ) AS variations ';

    -- Legalities
    command := command ||
                ', array(
                    SELECT row_to_json(x) FROM (
                        SELECT (SELECT row_to_json(a) FROM (select w.name) a) AS format,
                            (SELECT row_to_json(b) FROM (select x.name) b) AS legality
                        FROM cmcard_format_legality v left join cmformat w on v.cmformat = w.name
                        left join cmlegality x on v.cmlegality = x.name
                        WHERE v.cmcard = c.new_id
                        LIMIT 50
                    ) x
                ) AS format_legalities ';

    -- Frame Effects
    command := command ||
               ', array(
                    SELECT row_to_json(x) FROM (
                        SELECT w.description, w.id, w.name
                        FROM cmcard_frameeffect v left join cmframeeffect w on v.cmframeeffect = w.id
                        WHERE v.cmcard = c.new_id
                        LIMIT 50
                    ) x
                ) AS frame_effects ';

    -- Subtypes
    command := command ||
               ', array(
                    SELECT row_to_json(x) FROM (
                        SELECT w.name
                        FROM cmcard_subtype v left join cmcardtype w on v.cmcardtype = w.name
                        WHERE v.cmcard = c.new_id
                        LIMIT 50
                    ) x
                ) AS subtypes ';

    -- Supertypes
    command := command ||
               ', array(
                    SELECT row_to_json(x) FROM (
                        SELECT w.name
                        FROM cmcard_supertype v left join cmcardtype w on v.cmcardtype = w.name
                        WHERE v.cmcard = c.new_id
                        LIMIT 50
                    ) x
                ) AS supertypes ';

    -- Prices
    command := command ||
               ', array(
                    SELECT row_to_json(x) FROM (
                        SELECT v.id, v.low, v.median, v.high, v.market, v.direct_low, v.is_foil, v.date_updated
                        FROM cmcardprice v
                        WHERE v.cmcard = c.new_id
                        LIMIT 1
                    ) x
                ) AS prices ';

	-- Rulings
    command := command ||
               ', array(
                    SELECT row_to_json(x) FROM (
                        SELECT v.id, v.date_published, v.text
                        FROM cmruling v
                        WHERE v.oracle_id = c.oracle_id
                        LIMIT 100
                    ) x
                ) AS rulings ';

    command := command || 'FROM cmcard c WHERE c.new_id = ''' || _new_id || '''';

    RETURN QUERY EXECUTE command;
END;
$_$;


ALTER FUNCTION public.selectcard(character varying) OWNER TO managuide;

--
-- Name: selectcards(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: managuide
--

CREATE FUNCTION public.selectcards(character varying, character varying, character varying, character varying) RETURNS TABLE(new_id character varying, collector_number character varying, face_order integer, loyalty character varying, mana_cost character varying, number_order double precision, name character varying, name_section character varying, printed_name character varying, printed_type_line character varying, type_line character varying, power character varying, toughness character varying, tcgplayer_id integer, released_at date, art_crop_url character varying, normal_url character varying, png_url character varying, set json, rarity json, language json, layout json, prices json[], faces json[], supertypes json[])
    LANGUAGE plpgsql
    AS $_$
DECLARE
    _cmset ALIAS FOR $1;
    _cmlanguage ALIAS FOR $2;
    _sortedBy ALIAS FOR $3;
    _orderBy ALIAS FOR $4;
    command character varying;
BEGIN
    IF lower(_sortedBy) = 'set_name' THEN
        _sortedBy = 's.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
	IF lower(_sortedBy) = 'set_release' THEN
        _sortedBy = 's.release_date ' || _orderBy || ', s.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'collector_number' THEN
        _sortedBy = 'c.number_order ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'name' THEN
        _sortedBy = 'regexp_replace(c.name, ''"'', '''', ''g'')';
    END IF;
    IF lower(_sortedBy) = 'cmc' THEN
        _sortedBy = 'c.cmc ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'type' THEN
        _sortedBy = 'c.type_line ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'rarity' THEN
        _sortedBy = 'r.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;

    command := 'SELECT
                    new_id,
                    collector_number,
                    face_order,
                    loyalty,
                    mana_cost,
                    number_order,
                    c.name,
                    c.name_section,
                    printed_name,
                    printed_type_line,
                    type_line,
                    power,
                    toughness,
                    c.tcgplayer_id,
                    released_at,
                    art_crop_url,
                    normal_url,
                    png_url,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT s.code, s.name, s.keyrune_class, s.keyrune_unicode
                            FROM public.cmset s WHERE s.code = c.cmset
                            LIMIT 1
                        ) x
                    ) AS set,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT r.name
                            FROM public.cmrarity r WHERE r.name = c.cmrarity
                            LIMIT 1
                        ) x
                    ) AS rarity,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT l.code, l.display_code, l.name
                            FROM public.cmlanguage l WHERE l.code = c.cmlanguage
                            LIMIT 1
                        ) x
                    ) AS language,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.code, v.name, v.description
                            FROM public.cmlayout v
                            WHERE v.code = c.cmlayout
                            LIMIT 1
                        ) x
                    ) AS layout,
                    array(
                        SELECT row_to_json(x) FROM (
                            SELECT v.id, v.low, v.median, v.high, v.market, v.direct_low, v.is_foil, v.date_updated
                            FROM public.cmcardprice v
                            WHERE v.cmcard = c.new_id
                            LIMIT 1
                        ) x
                    ) AS prices ';

    -- Faces
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (
                            SELECT
                                new_id,
                                collector_number,
                                face_order,
                                loyalty,
                                mana_cost,
                                number_order,
                                name,
                                name_section,
                                printed_name,
                                printed_type_line,
                                type_line,
	                            power,
                                toughness,
                                art_crop_url,
                                normal_url,
                                png_url
                            FROM public.cmcard d left join public.cmcard_face w on w.cmcard_face = d.new_id
                            WHERE w.cmcard = c.new_id
                            ORDER BY face_order
                            LIMIT 10
                        ) x
                    ) AS faces ';

    -- Supertypes
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (
                            SELECT w.name
                            FROM public.cmcard_supertype v left join public.cmcardtype w on v.cmcardtype = w.name
                            WHERE v.cmcard = c.new_id
                            LIMIT 50
                        ) x
                    ) AS supertypes ';                

    command := command || 'FROM public.cmcard c LEFT JOIN public.cmset s ON c.cmset = s.code ';
	command := command || 'LEFT JOIN public.cmrarity r ON c.cmrarity = r.name ';
    command := command || 'WHERE c.cmset = ''' || _cmset || ''' ';
    command := command || 'AND c.cmlanguage = ''' || _cmlanguage || ''' ';
    command := command || 'AND c.new_id NOT IN(select cmcard_face from public.cmcard_face) ';
    command := command || 'ORDER BY ' || _sortedBy || '';

    RETURN QUERY EXECUTE command;
END;
$_$;


ALTER FUNCTION public.selectcards(character varying, character varying, character varying, character varying) OWNER TO managuide;

--
-- Name: selectcardsbyid(character varying[], character varying, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.selectcardsbyid(character varying[], character varying, character varying) RETURNS TABLE(new_id character varying, collector_number character varying, face_order integer, loyalty character varying, mana_cost character varying, number_order double precision, name character varying, name_section character varying, printed_name character varying, printed_type_line character varying, type_line character varying, power character varying, toughness character varying, tcgplayer_id integer, released_at date, art_crop_url character varying, normal_url character varying, png_url character varying, set json, rarity json, language json, layout json, prices json[], faces json[], supertypes json[])
    LANGUAGE plpgsql
    AS $_$
DECLARE
    _ids ALIAS FOR $1;
    _sortedBy ALIAS FOR $2;
    _orderBy ALIAS FOR $3;
    command character varying;
BEGIN
    IF lower(_sortedBy) = 'set_name' THEN
        _sortedBy = 's.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
	IF lower(_sortedBy) = 'set_release' THEN
        _sortedBy = 's.release_date ' || _orderBy || ', s.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'collector_number' THEN
        _sortedBy = 'c.number_order ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'name' THEN
        _sortedBy = 'regexp_replace(c.name, ''"'', '''', ''g'')';
    END IF;
    IF lower(_sortedBy) = 'cmc' THEN
        _sortedBy = 'c.cmc ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'type' THEN
        _sortedBy = 'c.type_line ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;
    IF lower(_sortedBy) = 'rarity' THEN
        _sortedBy = 'r.name ' || _orderBy || ', regexp_replace(c.name, ''"'', '''', ''g'') ' || _orderBy;
    END IF;

    command := 'SELECT
                    new_id,
                    collector_number,
                    face_order,
                    loyalty,
                    mana_cost,
                    number_order,
                    c.name,
                    c.name_section,
                    printed_name,
                    printed_type_line,
                    type_line,
                    power,
                    toughness,
                    c.tcgplayer_id,
                    released_at,
                    art_crop_url,
                    normal_url,
                    png_url,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT s.code, s.name, s.keyrune_class, s.keyrune_unicode
                            FROM public.cmset s WHERE s.code = c.cmset
                            LIMIT 1
                        ) x
                    ) AS set,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT r.name
                            FROM public.cmrarity r WHERE r.name = c.cmrarity
                            LIMIT 1
                        ) x
                    ) AS rarity,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT l.code, l.display_code, l.name
                            FROM public.cmlanguage l WHERE l.code = c.cmlanguage
                            LIMIT 1
                        ) x
                    ) AS language,
                    (
                        SELECT row_to_json(x) FROM (
                            SELECT v.code, v.name, v.description
                            FROM public.cmlayout v
                            WHERE v.code = c.cmlayout
                            LIMIT 1
                        ) x
                    ) AS layout,
                    array(
                        SELECT row_to_json(x) FROM (
                            SELECT v.id, v.low, v.median, v.high, v.market, v.direct_low, v.is_foil, v.date_updated
                            FROM public.cmcardprice v
                            WHERE v.cmcard = c.new_id
                            LIMIT 1
                        ) x
                    ) AS prices ';

    -- Faces
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (
                            SELECT
                                new_id,
                                collector_number,
                                face_order,
                                loyalty,
                                mana_cost,
                                number_order,
                                name,
                                name_section,
                                printed_name,
                                printed_type_line,
                                type_line,
	                            power,
                                toughness,
                                art_crop_url,
                                normal_url,
                                png_url
                            FROM public.cmcard d left join public.cmcard_face w on w.cmcard_face = d.new_id
                            WHERE w.cmcard = c.new_id
                            ORDER BY face_order
                            LIMIT 10
                        ) x
                    ) AS faces ';

    -- Supertypes
    command := command ||
                    ', array(
                        SELECT row_to_json(x) FROM (
                            SELECT w.name
                            FROM public.cmcard_supertype v left join public.cmcardtype w on v.cmcardtype = w.name
                            WHERE v.cmcard = c.new_id
                            LIMIT 50
                        ) x
                    ) AS supertypes ';                

    command := command || 'FROM public.cmcard c LEFT JOIN public.cmset s ON c.cmset = s.code ';
	command := command || 'LEFT JOIN public.cmrarity r ON c.cmrarity = r.name ';
    command := command || 'WHERE c.new_id IN';
	command := format('%s (%s) ', command, array_to_string(_ids, ','));
    command := format('%s ORDER BY %1s', command, _sortedBy);
    RAISE NOTICE 'Executing query: %', command;

    RETURN QUERY EXECUTE command;
END;
$_$;


ALTER FUNCTION public.selectcardsbyid(character varying[], character varying, character varying) OWNER TO postgres;

--
-- Name: selectotherprintings(character varying, character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: managuide
