    is_foil_only,
    is_online_only,
    logo_code,
    mtgo_code,
    keyrune_unicode,
    keyrune_class,
    year_section,
    name,
    release_date,
    tcgplayer_id,
    ( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT sb.code,
                    sb.name
                   FROM public.cmsetblock sb
                  WHERE ((sb.code)::text = (s.cmsetblock)::text)
                 LIMIT 1) x) AS set_block,
    ( SELECT row_to_json(x.*) AS row_to_json
