                     LEFT JOIN public.cmlanguage l ON (((sl.cmlanguage)::text = (l.code)::text)))
                  WHERE ((sl.cmset)::text = (s.code)::text)
                 LIMIT 100) x) AS languages,
    array_to_json(ARRAY( SELECT public.selectcards('lrw'::character varying, 'en'::character varying, 'name'::character varying, 'ASC'::character varying) AS selectcards)) AS cards
