CREATE MATERIALIZED VIEW public.matv_cmset_m10_it AS
 SELECT card_count,
    code,
    is_foil_only,
    is_online_only,
    logo_code,
    mtgo_code,
    keyrune_unicode,
    keyrune_class,
    year_section,
    name,
    release_date,
    tcgplayer_id,
    ( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT sb.code,
                    sb.name
                   FROM public.cmsetblock sb
                  WHERE ((sb.code)::text = (s.cmsetblock)::text)
                 LIMIT 1) x) AS set_block,
    ( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT st.name
                   FROM public.cmsettype st
                  WHERE ((st.name)::text = (s.cmsettype)::text)
                 LIMIT 1) x) AS set_type,
    ARRAY( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT l.code,
                    l.display_code,
                    l.name
                   FROM (public.cmset_language sl
                     LEFT JOIN public.cmlanguage l ON (((sl.cmlanguage)::text = (l.code)::text)))
                  WHERE ((sl.cmset)::text = (s.code)::text)
                 LIMIT 100) x) AS languages,
    array_to_json(ARRAY( SELECT public.selectcards('m10'::character varying, 'it'::character varying, 'name'::character varying, 'ASC'::character varying) AS selectcards)) AS cards
   FROM public.cmset s
  WHERE ((code)::text = 'm10'::text)
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.matv_cmset_m10_it OWNER TO managuide;

