--
-- Name: cmset cmset_pkey; Type: CONSTRAINT; Schema: public; Owner: managuide
--

ALTER TABLE ONLY public.cmset
    ADD CONSTRAINT cmset_pkey PRIMARY KEY (code);


--
-- Name: matv_cmsets; Type: MATERIALIZED VIEW; Schema: public; Owner: managuide
--

CREATE MATERIALIZED VIEW public.matv_cmsets AS
 SELECT card_count,
    code,
    is_foil_only,
    is_online_only,
    logo_code,
    mtgo_code,
    keyrune_unicode,
    keyrune_class,
    year_section,
    name,
    release_date,
    tcgplayer_id,
    cmset_parent,
    ( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT sb.code,
                    sb.name
                   FROM public.cmsetblock sb
                  WHERE ((sb.code)::text = (s.cmsetblock)::text)
                 LIMIT 1) x) AS set_block,
    ( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT st.name
                   FROM public.cmsettype st
                  WHERE ((st.name)::text = (s.cmsettype)::text)
                 LIMIT 1) x) AS set_type,
    ( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT sp.code
                   FROM public.cmset sp
                  WHERE ((sp.code)::text = (s.cmset_parent)::text)
                 LIMIT 1) x) AS set_parent,
    ARRAY( SELECT row_to_json(x.*) AS row_to_json
           FROM ( SELECT l.code,
                    l.display_code,
                    l.name
                   FROM (public.cmset_language sl
                     LEFT JOIN public.cmlanguage l ON (((sl.cmlanguage)::text = (l.code)::text)))
                  WHERE ((sl.cmset)::text = (s.code)::text)
                 LIMIT 100) x) AS languages
   FROM public.cmset s
  WHERE (card_count > 0)
  GROUP BY cmset_parent, card_count, code
  ORDER BY release_date DESC, cmset_parent DESC, name
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.matv_cmsets OWNER TO managuide;

